def test_domain_separator_is_distinct(self):
    chain = self._chain()
    binding = MerkleConsistencyChainReplayGuard().bind_once(chain, b"s")
    for other_domain in (
        b"zr/r/v1",
        b"zr/rr/v1",
        b"zr/rg/v1",
        b"zr/brg/v1",
        b"zr/brr/v1",
        b"zr/bsr/v1",
    ):
        # swapping only the domain separator must change the digest
        other_material = (
            len(other_domain).to_bytes(4, "big") + other_domain
            + self.expected_digest(chain, b"s")[0:0]
        )
        # rebuild the full chain framing under the foreign domain
        def F(item):
            return len(item).to_bytes(4, "big") + item

        def U(value):
            return value.to_bytes(8, "big")

        def S(sequence, transform):
            return F(U(len(sequence))) + b"".join(
                F(transform(item)) for item in sequence
            )

        def P(proof):
            return (
                F(U(proof.old_count))
                + F(U(proof.new_count))
                + S(proof.nodes, lambda node: node)
            )

        foreign_digest = hashlib.sha256(
            F(other_domain) + F(b"s") + S(chain.roots, lambda root: root)
            + S(chain.proofs, P) + F(b"\x00")
        ).digest()
        self.assertNotEqual(binding.digest, foreign_digest)
        self.assertEqual(other_material + b"", other_material)

